package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.annotation.WebFilter;

@WebFilter("/doLogin")
public class LoginCheckFilter implements Filter {
  public void init(FilterConfig config) throws ServletException { }
  public void doFilter(ServletRequest req, ServletResponse resp,
      FilterChain chain) throws IOException, ServletException {
    req.setCharacterEncoding("UTF-8");
    String user = req.getParameter("username");
    String pwd = req.getParameter("password");
    if (user == null || user.trim().equals("")
        || pwd == null || pwd.trim().equals("")) {
      req.setAttribute("msg", "用户名和密码不能为空");
      req.getRequestDispatcher("/login.jsp").forward(req, resp);
    } else {
      chain.doFilter(req, resp);
    }
  }
  public void destroy() { }
}

package com.demo;
import java.io.*;
import java.util.Date;
import javax.servlet.*;
import javax.servlet.annotation.WebListener;
import javax.servlet.http.HttpServletRequest;
@WebListener
public class UrlLogListener implements ServletRequestListener {
  public void requestInitialized(ServletRequestEvent sre) {
    HttpServletRequest req = (HttpServletRequest) sre.getServletRequest();
    String line = new Date() + " " + req.getRemoteAddr() + " " + req.getRequestURL();
    File f = new File(sre.getServletContext().getRealPath("/"), "access.log");
    synchronized (this) {
      try {
        PrintWriter pw = new PrintWriter(new FileWriter(f, true));
        pw.println(line);
        pw.close();
      } catch (IOException e) {
        sre.getServletContext().log("写日志失败", e);
      }
    }
  }
  public void requestDestroyed(ServletRequestEvent sre) { }
}
